CREATE TABLE well(id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(name)>0), details TEXT NOT NULL);
CREATE INDEX well_name ON well(name);
CREATE TABLE study(id TEXT PRIMARY KEY, well_id TEXT NOT NULL REFERENCES well(id) ON DELETE RESTRICT, observed_at TEXT, equipment TEXT NOT NULL CHECK(equipment IN ('new','old')), description TEXT NOT NULL, loader_version TEXT NOT NULL, input_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX study_well ON study(well_id, observed_at);
CREATE TABLE source_file(id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES study(id) ON DELETE RESTRICT, ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ('lvm','twf')), size INTEGER NOT NULL CHECK(size>=0), sha256 TEXT NOT NULL, payload BLOB NOT NULL CHECK(length(payload)=size), UNIQUE(study_id,ordinal), UNIQUE(id,study_id));
CREATE INDEX source_hash ON source_file(sha256);
CREATE TABLE numeric_array(id TEXT PRIMARY KEY, codec TEXT NOT NULL CHECK(codec='npy-v1'), dtype TEXT NOT NULL, shape TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, payload BLOB NOT NULL CHECK(length(payload)=size));
CREATE TABLE axis(id TEXT PRIMARY KEY, array_id TEXT NOT NULL REFERENCES numeric_array(id), meaning TEXT, units TEXT);
CREATE TABLE channel(id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES study(id), source_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('signal','noise')), axis_id TEXT NOT NULL REFERENCES axis(id), values_id TEXT NOT NULL REFERENCES numeric_array(id), units TEXT, transformation TEXT NOT NULL, UNIQUE(study_id,ordinal), UNIQUE(id,study_id), FOREIGN KEY(source_id,study_id) REFERENCES source_file(id,study_id));
CREATE TABLE processing_run(id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES study(id), input_hash TEXT NOT NULL, parameters TEXT NOT NULL, parameter_schema TEXT NOT NULL, algorithm_version TEXT NOT NULL, reference_hash TEXT NOT NULL, program_version TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('complete','failed')), failure TEXT, CHECK((status='complete' AND failure IS NULL) OR (status='failed' AND failure IS NOT NULL)), UNIQUE(id,study_id));
CREATE INDEX run_study ON processing_run(study_id,created_at);
CREATE TABLE run_input(run_id TEXT NOT NULL, study_id TEXT NOT NULL, channel_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), PRIMARY KEY(run_id,ordinal), UNIQUE(run_id,channel_id), FOREIGN KEY(run_id,study_id) REFERENCES processing_run(id,study_id), FOREIGN KEY(channel_id,study_id) REFERENCES channel(id,study_id));
CREATE TABLE result_signal(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES processing_run(id), name TEXT NOT NULL, axis_id TEXT NOT NULL REFERENCES axis(id), values_id TEXT NOT NULL REFERENCES numeric_array(id), units TEXT, UNIQUE(run_id,name));
CREATE TABLE result_statistics(run_id TEXT NOT NULL, study_id TEXT NOT NULL, channel_id TEXT NOT NULL, name TEXT NOT NULL, value_id TEXT NOT NULL REFERENCES numeric_array(id), units TEXT, PRIMARY KEY(run_id,channel_id,name), FOREIGN KEY(run_id,study_id) REFERENCES processing_run(id,study_id), FOREIGN KEY(channel_id,study_id) REFERENCES channel(id,study_id));
CREATE TABLE interpretation(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES processing_run(id), base_id TEXT, class_system TEXT NOT NULL, classes TEXT NOT NULL, arrays TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(id,run_id), FOREIGN KEY(base_id,run_id) REFERENCES interpretation(id,run_id));
CREATE TABLE interpretation_array(interpretation_id TEXT NOT NULL REFERENCES interpretation(id), name TEXT NOT NULL, array_id TEXT NOT NULL REFERENCES numeric_array(id), PRIMARY KEY(interpretation_id,name));
CREATE TABLE manual_correction(interpretation_id TEXT NOT NULL REFERENCES interpretation(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), signal_id TEXT NOT NULL REFERENCES result_signal(id), operation TEXT NOT NULL, parameters TEXT NOT NULL, author TEXT, created_at TEXT NOT NULL, PRIMARY KEY(interpretation_id,ordinal));
CREATE TABLE quality_interval(interpretation_id TEXT NOT NULL REFERENCES interpretation(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), axis_id TEXT NOT NULL REFERENCES axis(id), start REAL NOT NULL, end REAL NOT NULL CHECK(end>=start), class TEXT NOT NULL, boundary TEXT NOT NULL CHECK(boundary IN ('closed','left','right','open')), PRIMARY KEY(interpretation_id,ordinal));
CREATE TABLE report(id TEXT PRIMARY KEY, interpretation_id TEXT NOT NULL REFERENCES interpretation(id), details TEXT NOT NULL, template_version TEXT NOT NULL, template_hash TEXT NOT NULL, created_at TEXT NOT NULL, format TEXT NOT NULL, sha256 TEXT NOT NULL, payload BLOB NOT NULL);
CREATE INDEX report_interpretation ON report(interpretation_id);
